INSERT INTO `page_about_items` VALUES
(1,'Sobre Nós','<h2 class=\"elementor-heading-title elementor-size-default\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; line-height: 1.4em; font-size: 4.2vw; color: rgb(33, 33, 33); margin-block: 0.5rem 1rem; font-family: Poppins, sans-serif; padding: 0px; letter-spacing: -2px; outline: none !important;\">Seja bem vindo a Vila dos Carros, o primeiro shopping temático do Brasil<br style=\"outline: none !important;\"><span style=\"font-weight: bolder; outline: none !important;\">Vila dos Carros</span></h2><h2 class=\"elementor-heading-title elementor-size-default\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; line-height: 1.4em; font-size: 4.2vw; color: rgb(33, 33, 33); margin-block: 0.5rem 1rem; font-family: Poppins, sans-serif; padding: 0px; letter-spacing: -2px; outline: none !important;\"><span style=\"font-weight: bolder; outline: none !important;\"><br></span></h2><h2 class=\"elementor-heading-title elementor-size-default\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; line-height: 1.4em; font-size: 4.2vw; color: rgb(33, 33, 33); margin-block: 0.5rem 1rem; font-family: Poppins, sans-serif; padding: 0px; letter-spacing: -2px; outline: none !important;\"><span style=\"font-weight: bolder; outline: none !important;\"><p style=\"color: rgb(111, 111, 111); font-family: Jost, sans-serif; font-size: 16px; font-weight: 500; letter-spacing: normal;\"><span style=\"color: rgb(34, 34, 34); font-family: Poppins, sans-serif; font-size: 22px;\">No formato de vila/bairro ou bairro/vila, somos um shopping de automóveis inserido no fluxo de tráfego de veículos. Oferecemos um espaço aberto e arejado, onde não há “corredores”, mas sim alamedas, ruas ou avenidas. Somos uma referência não apenas para a região de Santos e Praia Grande, onde estamos localizados, mas para todo o país, redefinindo a experiência de comprar, vender ou trocar de carro.</span></p></span></h2><p style=\"color: rgb(111, 111, 111); font-family: Jost, sans-serif; font-size: 16px; font-weight: 500; letter-spacing: normal;\"><img src=\"data:image/png;base64,\" data-filename=\"ShoppingVilaDosCarros.png\" style=\"width: 640px;\"></p>','53f50d2bf215f178667bbd016538ba9d.jpg','Show','Sobre Nós','Somos um shopping de automóveis inserido no fluxo de tráfego de veículos.',NULL,'2024-11-19 21:38:53');
